import pandas as pd
import matplotlib.pyplot as plt

# 1. Load the CSV data generated by your ns-3 simulation
try:
    df = pd.read_csv('time_series_WEIGHTED_ROUND_ROBIN.csv')
except FileNotFoundError:
    print("Error: 'time_series_results.csv' not found. Make sure you ran the ns-3 simulation first.")
    exit()

# 2. Set up the figure and axis
fig, ax = plt.subplots(figsize=(10, 6))

# 3. Plot the data for each server
# Make Server 1 thicker so it acts as a background
ax.plot(df['Time_Seconds'], df['Server_1_Requests'], 
        label='Server 1 (Legacy, 2Mbps)', color='#E63946', linewidth=6)
        
ax.plot(df['Time_Seconds'], df['Server_2_Requests'], 
        label='Server 2 (Modern, Fails @ 4.0s)', color='#F4A261', linewidth=3, linestyle='--')
        
# Make Server 3 dashed and slightly thinner so Server 1 shows through
ax.plot(df['Time_Seconds'], df['Server_3_Requests'], 
        label='Server 3 (Modern, 100Mbps)', color='#2A9D8F', linewidth=3, linestyle='--')

# 4. Add the failover annotation at t = 4.0s
ax.axvline(x=4.0, color='black', linestyle=':', linewidth=2)
ax.annotate('Server 2 Hard Failure\n(t = 4.0s)', 
            xy=(4.0, df['Server_2_Requests'].max()), 
            xytext=(4.5, df['Server_2_Requests'].max() + 200),
            arrowprops=dict(facecolor='black', shrink=0.05, width=1.5, headwidth=8), 
            fontsize=11, fontweight='bold')

# 5. Format the chart with labels, title, and grid
ax.set_title('Cumulative Requests Handled Over Time', fontsize=14, fontweight='bold')
ax.set_xlabel('Simulation Time (seconds)', fontsize=12)
ax.set_ylabel('Cumulative Requests', fontsize=12)
ax.legend(loc='upper left', fontsize=11)
ax.grid(True, linestyle='--', alpha=0.6)

# 6. Adjust layout and display/save
plt.tight_layout()
plt.savefig('time_series_graph.png', dpi=300)
print("Graph saved successfully as 'time_series_graph.png'")
plt.show()
